customCSS:
.t, .history { color: #7f8490; }
.join { color: #9ed072; }
.part, .quit { color: #7f8490; }
.kick, .error { color: #fc5d7c; }
.notice { color: #e7c664; }
.action { color: #b39df3; }
.mode, .nick, .topic, .server { color: #f39660; }
.highlight { color: #e2e2e3; background-color: #414550; border-left: 3px solid #b39df3; padding-left: 8px; }
.reply { color: #7f8490; border-left: 2px solid #76cce0; padding-left: 6px; }
.oper { color: #2c2e34; background-color: #e7c664; }
.reactions { color: #76cce0; background-color: #3b3e48; }
.card { background-color: #3b3e48; border-color: #7f8490; }
.card-title { color: #76cce0; }
.card-desc { color: #7f8490; }
.daychange { color: #7f8490; border-color: #3b3e48; }
